/* San Jose MLS charts v2. Data is generated by scripts/build_san_jose_mls_v2.py. */
(function () {
  "use strict";

  if (!window.Chart || !window.SAN_JOSE_MLS_V2_DATA) return;

  var DATA = window.SAN_JOSE_MLS_V2_DATA;
  var MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  var COLORS = {
    teal: "#2c5364",
    tealFill: "rgba(44,83,100,0.10)",
    gold: "#d4a853",
    goldFill: "rgba(212,168,83,0.13)",
    blue: "#628aa0",
    blueFill: "rgba(98,138,160,0.11)",
    gray: "rgba(58,65,70,0.28)",
    grid: "rgba(0,0,0,0.055)",
    red: "#a85a4a"
  };

  var metricDefinitions = {
    salePrice: {
      canvas: "sjMlsV2SalePrice",
      snapshot: "sjMlsV2SnapshotSalePrice",
      change: "sjMlsV2ChangeSalePrice",
      label: "Sale Price",
      value: function (number) { return money(number); },
      tick: compactMoney,
      changeText: percentChange
    },
    daysOnMarket: {
      canvas: "sjMlsV2DaysOnMarket",
      snapshot: "sjMlsV2SnapshotDaysOnMarket",
      change: "sjMlsV2ChangeDaysOnMarket",
      label: "Days on Market",
      value: function (number) { return decimal(number, 0) + " days"; },
      tick: function (number) { return decimal(number, 0); },
      changeText: function (current, prior) {
        var difference = current - prior;
        return signedNumber(difference, 0) + " days year over year";
      }
    },
    saleToList: {
      canvas: "sjMlsV2SaleToList",
      snapshot: "sjMlsV2SnapshotSaleToList",
      change: "sjMlsV2ChangeSaleToList",
      label: "Sale-to-List Performance",
      value: function (number) { return decimal(number, 1) + "%"; },
      tick: function (number) { return decimal(number, 0) + "%"; },
      changeText: function (current, prior) {
        return signedNumber(current - prior, 1) + " points year over year";
      }
    },
    closedSales: {
      canvas: "sjMlsV2ClosedSales",
      snapshot: "sjMlsV2SnapshotClosedSales",
      change: "sjMlsV2ChangeClosedSales",
      label: "Closed-Sales Volume",
      value: function (number) { return Math.round(number).toLocaleString("en-US") + " sales"; },
      tick: function (number) { return Math.round(number).toLocaleString("en-US"); },
      changeText: percentChange
    },
    pricePerSqFt: {
      canvas: "sjMlsV2PricePerSqFt",
      snapshot: "sjMlsV2SnapshotPricePerSqFt",
      change: "sjMlsV2ChangePricePerSqFt",
      label: "Price per Square Foot",
      value: function (number) { return money(number) + "/sq ft"; },
      tick: function (number) { return "$" + Math.round(number); },
      changeText: percentChange
    }
  };

  var viewMode = "trend";
  var rangeMonths = 60;
  var timeCharts = [];
  var heatChart = null;

  function decimal(number, digits) {
    return Number(number).toLocaleString("en-US", {
      minimumFractionDigits: digits,
      maximumFractionDigits: digits
    });
  }

  function money(number) {
    return "$" + Math.round(number).toLocaleString("en-US");
  }

  function compactMoney(number) {
    var absolute = Math.abs(number);
    if (absolute >= 1000000) return "$" + (number / 1000000).toFixed(1) + "M";
    if (absolute >= 1000) return "$" + Math.round(number / 1000) + "K";
    return "$" + Math.round(number);
  }

  function signedNumber(number, digits) {
    var rounded = Number(number.toFixed(digits));
    if (rounded > 0) return "+" + decimal(rounded, digits);
    return decimal(rounded, digits);
  }

  function percentChange(current, prior) {
    var change = ((current / prior) - 1) * 100;
    return signedNumber(change, 1) + "% year over year";
  }

  function humanMonth(label) {
    var parts = label.split("-");
    return MONTHS[Number(parts[1]) - 1] + " " + parts[0];
  }

  function xScale() {
    return {
      grid: { display: false },
      ticks: {
        color: "#777",
        autoSkip: true,
        maxRotation: 0,
        maxTicksLimit: 9,
        font: { size: 10 },
        callback: function (value, index) {
          var label = this.chart.data.labels[index];
          if (!label) return "";
          var parts = label.split("-");
          var month = Number(parts[1]);
          return month === 1 ? "'" + parts[0].slice(2) : MONTHS[month - 1];
        }
      }
    };
  }

  function timeOptions(definition, showHundredLine) {
    return {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: "index", intersect: false },
      animation: { duration: 250 },
      plugins: {
        legend: {
          position: "bottom",
          labels: {
            color: "#606060",
            boxWidth: 22,
            boxHeight: 2,
            padding: 16,
            usePointStyle: false,
            font: { size: 11 }
          }
        },
        tooltip: {
          backgroundColor: "rgba(30,35,38,0.94)",
          padding: 11,
          titleFont: { size: 12 },
          bodyFont: { size: 12 },
          callbacks: {
            title: function (items) { return humanMonth(items[0].label); },
            label: function (context) {
              if (context.parsed.y === null) return context.dataset.label + ": unavailable";
              return context.dataset.label + ": " + definition.value(context.parsed.y);
            }
          }
        },
        sjReferenceLine: showHundredLine ? {
          y: 100,
          label: "100% of list price"
        } : false
      },
      scales: {
        x: xScale(),
        y: {
          beginAtZero: false,
          grid: { color: COLORS.grid },
          ticks: {
            color: "#777",
            maxTicksLimit: 6,
            font: { size: 10 },
            callback: definition.tick
          }
        }
      }
    };
  }

  var referenceLinePlugin = {
    id: "sjReferenceLine",
    afterDraw: function (chart, args, options) {
      if (!options || typeof options.y !== "number") return;
      var yScale = chart.scales.y;
      var xScaleObject = chart.scales.x;
      if (!yScale || !xScaleObject) return;
      var pixel = yScale.getPixelForValue(options.y);
      var context = chart.ctx;
      context.save();
      context.beginPath();
      context.setLineDash([5, 5]);
      context.strokeStyle = "rgba(212,168,83,0.85)";
      context.lineWidth = 1;
      context.moveTo(xScaleObject.left, pixel);
      context.lineTo(xScaleObject.right, pixel);
      context.stroke();
      context.setLineDash([]);
      context.fillStyle = "#9a742b";
      context.font = "10px DM Sans, sans-serif";
      context.textAlign = "right";
      context.fillText(options.label || "", xScaleObject.right - 3, pixel - 6);
      context.restore();
    }
  };

  var heatReferencePlugin = {
    id: "sjHeatReference",
    afterDraw: function (chart) {
      var xScaleObject = chart.scales.x;
      var yScaleObject = chart.scales.y;
      if (!xScaleObject || !yScaleObject) return;
      var context = chart.ctx;
      var xPixel = xScaleObject.getPixelForValue(14);
      var yPixel = yScaleObject.getPixelForValue(100);
      context.save();
      context.strokeStyle = "rgba(212,168,83,0.62)";
      context.lineWidth = 1;
      context.setLineDash([5, 5]);
      context.beginPath();
      context.moveTo(xPixel, yScaleObject.top);
      context.lineTo(xPixel, yScaleObject.bottom);
      context.moveTo(xScaleObject.left, yPixel);
      context.lineTo(xScaleObject.right, yPixel);
      context.stroke();
      context.setLineDash([]);
      context.fillStyle = "#8b6a2d";
      context.font = "10px DM Sans, sans-serif";
      context.textAlign = "left";
      context.fillText("Above list", xScaleObject.left + 7, yPixel - 7);
      context.textAlign = "right";
      context.fillText("Under list", xScaleObject.right - 5, yPixel + 14);
      context.restore();
    }
  };

  function createTimeChart(metricKey) {
    var definition = metricDefinitions[metricKey];
    var series = DATA.series[metricKey];
    var canvas = document.getElementById(definition.canvas);
    if (!canvas) return;

    var datasets = [
      {
        key: "raw",
        label: "Actual monthly",
        data: series.raw.slice(),
        borderColor: COLORS.gold,
        backgroundColor: COLORS.goldFill,
        borderWidth: 1.5,
        borderDash: [4, 4],
        pointRadius: 0,
        pointHoverRadius: 4,
        spanGaps: false,
        tension: 0.16
      },
      {
        key: "adjusted",
        label: "Seasonally adjusted",
        data: series.adjusted.slice(),
        borderColor: COLORS.blue,
        backgroundColor: COLORS.blueFill,
        borderWidth: 1.7,
        pointRadius: 0,
        pointHoverRadius: 4,
        spanGaps: false,
        tension: 0.18
      },
      {
        key: "trend",
        label: "3-month trend",
        data: series.trend.slice(),
        borderColor: COLORS.teal,
        backgroundColor: COLORS.tealFill,
        borderWidth: 3,
        pointRadius: 0,
        pointHoverRadius: 4,
        spanGaps: true,
        fill: false,
        tension: 0.22
      }
    ];

    var chart = new Chart(canvas, {
      type: "line",
      data: {
        labels: series.labels.slice(),
        datasets: datasets
      },
      options: timeOptions(definition, metricKey === "saleToList"),
      plugins: [referenceLinePlugin]
    });

    timeCharts.push({
      chart: chart,
      labels: series.labels.slice(),
      datasets: {
        raw: series.raw.slice(),
        adjusted: series.adjusted.slice(),
        trend: series.trend.slice()
      }
    });
  }

  function updateSnapshots() {
    Object.keys(metricDefinitions).forEach(function (metricKey) {
      var definition = metricDefinitions[metricKey];
      var series = DATA.series[metricKey];
      var lastIndex = series.raw.length - 1;
      var priorIndex = lastIndex - 12;
      var current = series.raw[lastIndex];
      var prior = series.raw[priorIndex];
      var valueElement = document.getElementById(definition.snapshot);
      var changeElement = document.getElementById(definition.change);
      if (valueElement) valueElement.textContent = definition.value(current);
      if (changeElement) {
        changeElement.textContent = definition.changeText(current, prior);
        changeElement.setAttribute("title", humanMonth(series.labels[priorIndex]) + " comparison");
      }
    });

    var dateElements = document.querySelectorAll("[data-sj-mls-latest-month]");
    dateElements.forEach(function (element) {
      element.textContent = humanMonth(DATA.metadata.latestMonth);
    });
  }

  function heatPoints() {
    var dom = DATA.series.daysOnMarket;
    var saleToList = DATA.series.saleToList;
    var sales = DATA.series.closedSales;
    var saleMap = {};
    var volumeMap = {};
    var rawDomMap = {};
    var rawSaleMap = {};

    saleToList.labels.forEach(function (label, index) {
      saleMap[label] = saleToList.adjusted[index];
      rawSaleMap[label] = saleToList.raw[index];
    });
    sales.labels.forEach(function (label, index) {
      volumeMap[label] = sales.raw[index];
    });
    dom.labels.forEach(function (label, index) {
      rawDomMap[label] = dom.raw[index];
    });

    return dom.labels.map(function (label, index) {
      return {
        x: dom.adjusted[index],
        y: saleMap[label],
        date: label,
        volume: volumeMap[label],
        rawDom: rawDomMap[label],
        rawSaleToList: rawSaleMap[label]
      };
    }).filter(function (point) {
      return point.x !== null && point.y !== null && point.volume !== null;
    });
  }

  function heatRadius(context) {
    var volume = context.raw && context.raw.volume ? context.raw.volume : 400;
    return Math.max(3, Math.min(8, Math.sqrt(volume) / 4.2));
  }

  function createHeatChart() {
    var canvas = document.getElementById("sjMlsV2Heat");
    if (!canvas) return;
    var points = heatPoints();
    var cutoff = Math.max(0, points.length - 12);
    var history = points.slice(0, cutoff);
    var recent = points.slice(cutoff);
    var latest = recent.length ? [recent[recent.length - 1]] : [];

    heatChart = new Chart(canvas, {
      type: "scatter",
      data: {
        datasets: [
          {
            label: "Earlier months",
            data: history,
            backgroundColor: COLORS.gray,
            borderColor: "rgba(58,65,70,0.34)",
            pointRadius: heatRadius,
            pointHoverRadius: function (context) { return heatRadius(context) + 2; }
          },
          {
            label: "Latest 12 months",
            data: recent,
            backgroundColor: "rgba(44,83,100,0.58)",
            borderColor: COLORS.teal,
            pointRadius: heatRadius,
            pointHoverRadius: function (context) { return heatRadius(context) + 2; }
          },
          {
            label: "Latest month",
            data: latest,
            backgroundColor: COLORS.gold,
            borderColor: "#ffffff",
            borderWidth: 2,
            pointRadius: 9,
            pointHoverRadius: 10
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 250 },
        interaction: { mode: "nearest", intersect: true },
        plugins: {
          legend: {
            position: "bottom",
            labels: {
              color: "#606060",
              boxWidth: 10,
              boxHeight: 10,
              padding: 15,
              font: { size: 11 }
            }
          },
          tooltip: {
            backgroundColor: "rgba(30,35,38,0.94)",
            padding: 11,
            callbacks: {
              title: function (items) { return humanMonth(items[0].raw.date); },
              label: function (context) {
                var point = context.raw;
                return [
                  "Adjusted days on market: " + decimal(point.x, 1),
                  "Adjusted sale-to-list: " + decimal(point.y, 1) + "%",
                  "Actual closed sales: " + Math.round(point.volume).toLocaleString("en-US")
                ];
              }
            }
          }
        },
        scales: {
          x: {
            title: { display: true, text: "Days on Market (seasonally adjusted)", color: "#555" },
            grid: { color: COLORS.grid },
            ticks: { color: "#777", font: { size: 10 } }
          },
          y: {
            title: { display: true, text: "Sale-to-List Performance (seasonally adjusted)", color: "#555" },
            grid: { color: COLORS.grid },
            ticks: {
              color: "#777",
              font: { size: 10 },
              callback: function (number) { return decimal(number, 0) + "%"; }
            }
          }
        }
      },
      plugins: [heatReferencePlugin]
    });
    heatChart.$allPoints = points;
  }

  function createNewListingsChart() {
    var canvas = document.getElementById("sjMlsV2NewListings");
    if (!canvas) return;
    var rows = DATA.newListings.slice().reverse();
    new Chart(canvas, {
      type: "bar",
      data: {
        labels: rows.map(function (row) { return row.city; }),
        datasets: [{
          label: "Stored five-year total",
          data: rows.map(function (row) { return row.value; }),
          backgroundColor: rows.map(function (row) {
            return row.city === "San Jose" ? COLORS.teal : "rgba(98,138,160,0.42)";
          }),
          borderColor: rows.map(function (row) {
            return row.city === "San Jose" ? COLORS.teal : "rgba(98,138,160,0.62)";
          }),
          borderWidth: 1,
          borderRadius: 4
        }]
      },
      options: {
        indexAxis: "y",
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 250 },
        plugins: {
          legend: { display: false },
          tooltip: {
            backgroundColor: "rgba(30,35,38,0.94)",
            padding: 11,
            callbacks: {
              label: function (context) {
                return context.parsed.x.toLocaleString("en-US") + " new listings";
              }
            }
          }
        },
        scales: {
          x: {
            beginAtZero: true,
            grid: { color: COLORS.grid },
            ticks: {
              color: "#777",
              font: { size: 10 },
              callback: function (number) { return Math.round(number / 1000) + "K"; }
            }
          },
          y: {
            grid: { display: false },
            ticks: {
              color: function (context) {
                return rows[context.index].city === "San Jose" ? COLORS.teal : "#555";
              },
              font: function (context) {
                return {
                  size: 11,
                  weight: rows[context.index].city === "San Jose" ? "bold" : "normal"
                };
              }
            }
          }
        }
      }
    });
  }

  function applyViewMode() {
    timeCharts.forEach(function (entry) {
      entry.chart.data.datasets.forEach(function (dataset) {
        if (viewMode === "trend") dataset.hidden = dataset.key !== "trend";
        if (viewMode === "adjusted") dataset.hidden = dataset.key === "raw";
        if (viewMode === "actual") dataset.hidden = dataset.key === "adjusted";
      });
      entry.chart.update();
    });

    var modeNotes = {
      trend: "Showing the 3-month trend after seasonal adjustment.",
      adjusted: "Showing seasonally adjusted monthly data with the 3-month trend.",
      actual: "Showing actual monthly data with the seasonally adjusted 3-month trend."
    };
    var note = document.getElementById("sjMlsV2ModeNote");
    if (note) note.textContent = modeNotes[viewMode];
  }

  function applyRange() {
    timeCharts.forEach(function (entry) {
      var start = rangeMonths > 0 ? Math.max(0, entry.labels.length - rangeMonths) : 0;
      entry.chart.data.labels = entry.labels.slice(start);
      entry.chart.data.datasets.forEach(function (dataset) {
        dataset.data = entry.datasets[dataset.key].slice(start);
      });
      entry.chart.update();
    });

    if (heatChart) {
      var points = heatChart.$allPoints;
      var labelSeries = DATA.series.daysOnMarket.labels;
      var startIndex = rangeMonths > 0 ? Math.max(0, labelSeries.length - rangeMonths) : 0;
      var firstLabel = labelSeries[startIndex];
      var visible = points.filter(function (point) { return point.date >= firstLabel; });
      var recentCutoff = Math.max(0, visible.length - 12);
      heatChart.data.datasets[0].data = visible.slice(0, recentCutoff);
      heatChart.data.datasets[1].data = visible.slice(recentCutoff);
      heatChart.data.datasets[2].data = visible.length ? [visible[visible.length - 1]] : [];
      heatChart.update();
    }
  }

  function bindControls() {
    var rangeButtons = document.querySelectorAll("[data-sj-mls-range]");
    rangeButtons.forEach(function (button) {
      button.addEventListener("click", function () {
        rangeMonths = Number(button.getAttribute("data-sj-mls-range"));
        rangeButtons.forEach(function (item) {
          var active = item === button;
          item.classList.toggle("active", active);
          item.setAttribute("aria-pressed", active ? "true" : "false");
        });
        applyRange();
      });
    });

    var viewButtons = document.querySelectorAll("[data-sj-mls-view]");
    viewButtons.forEach(function (button) {
      button.addEventListener("click", function () {
        viewMode = button.getAttribute("data-sj-mls-view");
        viewButtons.forEach(function (item) {
          var active = item === button;
          item.classList.toggle("active", active);
          item.setAttribute("aria-pressed", active ? "true" : "false");
        });
        applyViewMode();
      });
    });
  }

  Object.keys(metricDefinitions).forEach(createTimeChart);
  createHeatChart();
  createNewListingsChart();
  updateSnapshots();
  bindControls();
  applyViewMode();
  applyRange();
})();
